"""Generate code-native 1-bit sprites. Does not edit external reference images."""
from pathlib import Path
import sys,json
from gotchi_catalog import ROOT,PETS
assert len(PETS)==16
for pet in PETS:
 assert len(pet['rows'])==16 and all(len(row)==4 and 0<=int(row,16)<=65535 for row in pet['rows'])
lines=["#ifndef MESHIGOTCHI_GOTCHI_SPRITES_H","#define MESHIGOTCHI_GOTCHI_SPRITES_H","// Generated by tools/generate_gotchi_catalog.py from assets/gotchi_board/catalog.json.","#include <stdint.h>","#ifndef MESHIGOTCHI_DEFAULT_GOTCHI","#define MESHIGOTCHI_DEFAULT_GOTCHI 0","#endif","namespace meshigotchi_gotchi {",f"constexpr uint8_t count={len(PETS)};","constexpr uint8_t boardPageSize=6;","static_assert(MESHIGOTCHI_DEFAULT_GOTCHI>=0 && MESHIGOTCHI_DEFAULT_GOTCHI<count,\"Gotchi default outside Board\");","constexpr uint8_t defaultPet=MESHIGOTCHI_DEFAULT_GOTCHI;","inline uint8_t valid(uint8_t pet){return pet<count?pet:defaultPet;}"]
for function,key in [('name','name'),('description','description')]:
 values=','.join(json.dumps(p[key],ensure_ascii=False) for p in PETS)
 lines.append('inline const char* '+function+'(uint8_t pet){static const char* const names[]={'+values+'};return names[valid(pet)];}')
lines+=['// One constant-initialized COMDAT instance across firmware translation units.','inline const uint16_t (&artwork())[count][16]{','static const uint16_t pixels[count][16]={']
for p in PETS:lines.append('  {'+','.join('0x'+row for row in p['rows'])+'}, // '+p['name'])
lines+=['};return pixels;','}',f'static_assert(sizeof(artwork())=={len(PETS)*32},"Sprite flash budget");','inline uint8_t eye(uint8_t pet,unsigned coordinate){','  static const uint8_t positions[count-6][4]={']
for p in PETS[6:]:lines.append('    {'+','.join(map(str,p['eyes']))+'}, // '+p['name'])
lines+=['  };return positions[valid(pet)>=6?valid(pet)-6:0][coordinate%4];','}', 'template<class D> void sprite(D& d,uint8_t pet,int x,int y,int scale=1){','  for(int row=0;row<16;++row)for(int col=0;col<16;++col)','    if(artwork()[valid(pet)][row] & (0x8000u>>col))d.fillRect(x+col*scale,y+row*scale,scale,scale);','}','}','#endif']
output='\n'.join(lines)+'\n';target=ROOT/'firmware/ui/GotchiSprites.h'
if '--check' in sys.argv:assert target.read_text()==output,'Run tools/generate_gotchi_catalog.py'
else:target.write_text(output)
print('PASS: 16 unique code-native sprites, 512 bitmap bytes; catalog/header parity')
